mapper.select:
SELECT rna.id AS application_id, rna.user_id, u.nick_name AS nickname, AS phone_masked, rna.status, rna.real_name_mask AS real_name_masked, rna.id_number_mask AS id_number_masked, rna.reject_reason, au.nick_name AS reviewer_name, rna.create_time AS submitted_at, rna.audited_at AS reviewed_at FROM user_real_name_auth rna JOIN sys_user u ON u.user_id = rna.user_id LEFT JOIN sys_user au ON au.user_id = rna.auditor_id WHERE 1 = 1
AND rna.status = #{status}
AND ( u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%') )
AND rna.create_time >= #{beginTime}
AND rna.create_time <= #{endTime}
ORDER BY ${orderByColumn} ${isAsc}
